cat > /mnt/user-data/outputs/llm-skillmap/00-master-map.html << 'HTMLEOF'
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>LLM 核心技能宇宙图谱</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

  :root {
    --bg: #070B14;
    --surface: #0D1320;
    --border: #1A2540;
    --text-primary: #E8EEFF;
    --text-muted: #5A6A8A;
    --text-dim: #3A4A6A;

    /* Pillar colors */
    --pre-base: #1B5E8A;
    --pre-mid: #2E86C1;
    --pre-bright: #5DADE2;
    --pre-glow: rgba(93,173,226,0.15);

    --post-base: #7B1F8C;
    --post-mid: #A040C0;
    --post-bright: #D070F0;
    --post-glow: rgba(208,112,240,0.15);

    --agent-base: #1A7A4A;
    --agent-mid: #28A060;
    --agent-bright: #4DC880;
    --agent-glow: rgba(77,200,128,0.15);

    --accent-gold: #F0B429;
    --accent-red: #E55050;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: var(--bg);
    color: var(--text-primary);
    font-family: 'Inter', sans-serif;
    min-height: 100vh;
    overflow-x: hidden;
  }

  .header {
    text-align: center;
    padding: 48px 24px 32px;
    position: relative;
  }

  .header::before {
    content: '';
    position: absolute;
    top: 0; left: 50%;
    transform: translateX(-50%);
    width: 600px; height: 200px;
    background: radial-gradient(ellipse, rgba(93,173,226,0.08) 0%, transparent 70%);
    pointer-events: none;
  }

  .eyebrow {
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 3px;
    color: var(--accent-gold);
    text-transform: uppercase;
    margin-bottom: 16px;
  }

  h1 {
    font-size: clamp(24px, 4vw, 42px);
    font-weight: 700;
    line-height: 1.1;
    letter-spacing: -0.02em;
    margin-bottom: 12px;
  }

  h1 span.pre { color: var(--pre-bright); }
  h1 span.post { color: var(--post-bright); }
  h1 span.agent { color: var(--agent-bright); }

  .subtitle {
    color: var(--text-muted);
    font-size: 14px;
    font-weight: 400;
    max-width: 600px;
    margin: 0 auto;
    line-height: 1.6;
  }

  /* Stats bar */
  .stats-bar {
    display: flex;
    justify-content: center;
    gap: 40px;
    padding: 20px;
    margin: 16px auto 0;
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
    max-width: 900px;
  }

  .stat {
    text-align: center;
  }

  .stat-num {
    font-family: 'JetBrains Mono', monospace;
    font-size: 28px;
    font-weight: 700;
    color: var(--accent-gold);
  }

  .stat-label {
    font-size: 11px;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-top: 2px;
  }

  /* Main grid */
  .pillars {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 2px;
    max-width: 1400px;
    margin: 32px auto;
    padding: 0 16px;
  }

  .pillar {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 0;
    overflow: hidden;
    position: relative;
  }

  .pillar:first-child { border-radius: 12px 0 0 12px; }
  .pillar:last-child { border-radius: 0 12px 12px 0; }

  .pillar-header {
    padding: 24px 20px 20px;
    border-bottom: 1px solid var(--border);
    position: relative;
  }

  .pillar-id {
    font-family: 'JetBrains Mono', monospace;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 2px;
    margin-bottom: 8px;
    opacity: 0.7;
  }

  .pillar-title {
    font-size: 18px;
    font-weight: 700;
    margin-bottom: 4px;
  }

  .pillar-desc {
    font-size: 12px;
    color: var(--text-muted);
    line-height: 1.5;
  }

  .pillar-stripe {
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 2px;
  }

  /* Skill cards */
  .skills-list {
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .skill-card {
    padding: 14px 16px;
    border: 1px solid transparent;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
    position: relative;
    overflow: hidden;
  }

  .skill-card:hover {
    border-color: currentColor;
    transform: translateX(4px);
  }

  .skill-card::before {
    content: '';
    position: absolute;
    inset: 0;
    opacity: 0;
    transition: opacity 0.2s;
  }

  .skill-card:hover::before {
    opacity: 1;
  }

  .skill-code {
    font-family: 'JetBrains Mono', monospace;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 1px;
    opacity: 0.6;
    margin-bottom: 4px;
  }

  .skill-name {
    font-size: 13px;
    font-weight: 600;
    margin-bottom: 6px;
    line-height: 1.3;
  }

  .skill-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
  }

  .tag {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    font-weight: 500;
    padding: 2px 6px;
    border-radius: 3px;
    letter-spacing: 0.5px;
    opacity: 0.7;
  }

  /* Pretraining colors */
  .pillar-pre .pillar-id { color: var(--pre-bright); }
  .pillar-pre .pillar-title { color: var(--pre-bright); }
  .pillar-pre .pillar-stripe { background: linear-gradient(90deg, var(--pre-base), var(--pre-bright)); }
  .pillar-pre .skill-card { background: rgba(46,134,193,0.04); }
  .pillar-pre .skill-card:hover { background: var(--pre-glow); color: var(--pre-bright); }
  .pillar-pre .skill-card:hover::before { background: var(--pre-glow); }
  .pillar-pre .skill-code { color: var(--pre-bright); }
  .pillar-pre .skill-card:hover .skill-name { color: var(--pre-bright); }
  .pillar-pre .tag { background: rgba(46,134,193,0.15); color: var(--pre-bright); }

  /* Post-training colors */
  .pillar-post .pillar-id { color: var(--post-bright); }
  .pillar-post .pillar-title { color: var(--post-bright); }
  .pillar-post .pillar-stripe { background: linear-gradient(90deg, var(--post-base), var(--post-bright)); }
  .pillar-post .skill-card { background: rgba(160,64,192,0.04); }
  .pillar-post .skill-card:hover { background: var(--post-glow); color: var(--post-bright); }
  .pillar-post .skill-card:hover::before { background: var(--post-glow); }
  .pillar-post .skill-code { color: var(--post-bright); }
  .pillar-post .skill-card:hover .skill-name { color: var(--post-bright); }
  .pillar-post .tag { background: rgba(160,64,192,0.15); color: var(--post-bright); }

  /* Agent colors */
  .pillar-agent .pillar-id { color: var(--agent-bright); }
  .pillar-agent .pillar-title { color: var(--agent-bright); }
  .pillar-agent .pillar-stripe { background: linear-gradient(90deg, var(--agent-base), var(--agent-bright)); }
  .pillar-agent .skill-card { background: rgba(40,160,96,0.04); }
  .pillar-agent .skill-card:hover { background: var(--agent-glow); color: var(--agent-bright); }
  .pillar-agent .skill-card:hover::before { background: var(--agent-glow); }
  .pillar-agent .skill-code { color: var(--agent-bright); }
  .pillar-agent .skill-card:hover .skill-name { color: var(--agent-bright); }
  .pillar-agent .tag { background: rgba(40,160,96,0.15); color: var(--agent-bright); }

  /* Connections section */
  .connections {
    max-width: 1400px;
    margin: 32px auto;
    padding: 0 16px;
  }

  .connections-title {
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 2px;
    color: var(--accent-gold);
    text-transform: uppercase;
    margin-bottom: 20px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--border);
  }

  .conn-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
  }

  .conn-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px;
  }

  .conn-type {
    font-family: 'JetBrains Mono', monospace;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 1px;
    color: var(--accent-gold);
    margin-bottom: 12px;
    text-transform: uppercase;
  }

  .conn-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 8px;
    line-height: 1.4;
  }

  .conn-arrow {
    color: var(--accent-gold);
    flex-shrink: 0;
    font-family: 'JetBrains Mono', monospace;
    font-size: 12px;
  }

  .conn-codes {
    font-family: 'JetBrains Mono', monospace;
    font-size: 10px;
    color: var(--text-primary);
    background: var(--bg);
    padding: 2px 6px;
    border-radius: 3px;
    flex-shrink: 0;
  }

  /* Hiring matrix */
  .hiring-matrix {
    max-width: 1400px;
    margin: 32px auto;
    padding: 0 16px 48px;
  }

  .matrix-title {
    font-family: 'JetBrains Mono', monospace;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 2px;
    color: var(--accent-gold);
    text-transform: uppercase;
    margin-bottom: 20px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--border);
  }

  .matrix-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
  }

  .matrix-table th {
    text-align: left;
    padding: 10px 14px;
    background: var(--surface);
    border: 1px solid var(--border);
    font-family: 'JetBrains Mono', monospace;
    font-size: 10px;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--text-muted);
    font-weight: 600;
  }

  .matrix-table td {
    padding: 10px 14px;
    border: 1px solid var(--border);
    vertical-align: top;
    color: var(--text-muted);
    line-height: 1.5;
  }

  .matrix-table tr:hover td {
    background: var(--surface);
  }

  .role-name {
    font-weight: 600;
    color: var(--text-primary);
    font-size: 13px;
  }

  .skill-badges {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
  }

  .skill-badge {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px;
    padding: 2px 6px;
    border-radius: 3px;
    font-weight: 600;
  }

  .badge-pre { background: rgba(46,134,193,0.15); color: var(--pre-bright); }
  .badge-post { background: rgba(160,64,192,0.15); color: var(--post-bright); }
  .badge-agent { background: rgba(40,160,96,0.15); color: var(--agent-bright); }
  .badge-core { background: rgba(240,180,41,0.15); color: var(--accent-gold); }

  .level-bar {
    display: flex;
    gap: 3px;
    margin-top: 4px;
  }

  .level-dot {
    width: 8px; height: 8px;
    border-radius: 50%;
    background: var(--border);
  }

  .level-dot.filled { background: var(--accent-gold); }

  @media (max-width: 900px) {
    .pillars { grid-template-columns: 1fr; }
    .pillar:first-child { border-radius: 12px 12px 0 0; }
    .pillar:last-child { border-radius: 0 0 12px 12px; }
    .conn-grid { grid-template-columns: 1fr; }
    .stats-bar { gap: 20px; flex-wrap: wrap; }
  }
</style>
</head>
<body>

<div class="header">
  <div class="eyebrow">OpenAI · Anthropic · Meta · xAI · DeepMind</div>
  <h1>LLM 工程师 <span class="pre">核心技能</span> 全景<span class="post">宇宙</span><span class="agent">图谱</span></h1>
  <p class="subtitle">18 个元技能 · 3 大支柱 · 覆盖预训练 / 后训练 / Agent 工程 全链路招聘要求</p>
  <div class="stats-bar">
    <div class="stat"><div class="stat-num">3</div><div class="stat-label">核心支柱</div></div>
    <div class="stat"><div class="stat-num">18</div><div class="stat-label">元技能</div></div>
    <div class="stat"><div class="stat-num">47+</div><div class="stat-label">子技能点</div></div>
    <div class="stat"><div class="stat-num">120+</div><div class="stat-label">关键论文/仓库</div></div>
  </div>
</div>

<div class="pillars">

  <!-- PRETRAINING -->
  <div class="pillar pillar-pre">
    <div class="pillar-header">
      <div class="pillar-id">PILLAR I · PRETRAINING</div>
      <div class="pillar-title">预训练工程</div>
      <div class="pillar-desc">从原始语料到基础模型：数据、架构、分布式、稳定性</div>
      <div class="pillar-stripe"></div>
    </div>
    <div class="skills-list">
      <div class="skill-card">
        <div class="skill-code">MS-01</div>
        <div class="skill-name">数据工程 & 语料库构建</div>
