      </div>
      <div class="skill-card">
        <div class="skill-code">MS-05</div>
        <div class="skill-name">Scaling Laws & 算力效率</div>
        <div class="skill-tags">
          <span class="tag">Chinchilla</span>
          <span class="tag">FLOPs</span>
          <span class="tag">MFU</span>
          <span class="tag">anneal</span>
        </div>
      </div>
      <div class="skill-card">
        <div class="skill-code">MS-06</div>
        <div class="skill-name">GPU 基础设施 & 系统编程</div>
        <div class="skill-tags">
          <span class="tag">CUDA</span>
          <span class="tag">NCCL</span>
          <span class="tag">FlashAttn</span>
          <span class="tag">profiling</span>
        </div>
      </div>
    </div>
  </div>

  <!-- POST-TRAINING -->
  <div class="pillar pillar-post">
    <div class="pillar-header">
      <div class="pillar-id">PILLAR II · POST-TRAINING</div>
      <div class="pillar-title">后训练对齐</div>
      <div class="pillar-desc">从基础模型到对齐助手：SFT、RLHF、DPO、推理增强</div>
      <div class="pillar-stripe"></div>
    </div>
    <div class="skills-list">
      <div class="skill-card">
        <div class="skill-code">MS-07</div>
        <div class="skill-name">监督微调 (SFT)</div>
        <div class="skill-tags">
          <span class="tag">instruction tune</span>
          <span class="tag">chat template</span>
          <span class="tag">data quality</span>
        </div>
      </div>
      <div class="skill-card">
        <div class="skill-code">MS-08</div>
        <div class="skill-name">奖励建模 & 偏好数据</div>
