</div>

<!-- Connections -->
<div class="connections">
  <div class="connections-title">元技能衔接关系 · Cross-Skill Dependencies</div>
  <div class="conn-grid">
    <div class="conn-card">
      <div class="conn-type">纵向链路 · 支柱内部</div>
